WITH matched_keys AS (SELECT customer_id, id FROM sessions EXCEPT ALL SELECT customer_id, id FROM sessions WHERE HOUR(started_at) BETWEEN 9 AND 15), verified AS (SELECT s.* FROM sessions s INNER JOIN matched_keys k ON s.customer_id = k.customer_id AND s.id = k.id) SELECT DATE_TRUNC('YEAR', started_at) AS year_start, browser, DATE_TRUNC('MONTH', started_at) AS activity_month, COUNT(CASE WHEN country = 'DE' THEN 1 END) AS de_count, MAX(started_at) AS ended_at, COUNT_IF(browser = 'Safari') AS safari_events, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, MIN(started_at) AS first_started_at, COUNT(CASE WHEN device = 'tablet' THEN 1 END) AS tablet_count, GROUPING(DATE_TRUNC('YEAR', started_at)) AS grouping_id FROM verified GROUP BY CUBE (DATE_TRUNC('YEAR', started_at), browser, DATE_TRUNC('MONTH', started_at)) ORDER BY year_start NULLS FIRST;
